  --card-foreground: 210 50% 22%;

  --card-border: 30 20% 88%;

  --sidebar: 40 25% 93%;

  --sidebar-foreground: 210 50% 25%;

  --sidebar-border: 30 15% 83%;

  --sidebar-primary: 25 90% 55%;

  --sidebar-primary-foreground: 40 25% 98%;

  --sidebar-accent: 40 20% 88%;

  --sidebar-accent-foreground: 210 50% 28%;

  --sidebar-ring: 25 85% 60%;

  --popover: 40 25% 94%;

  --popover-foreground: 210 50% 24%;

  --popover-border: 30 15% 82%;

  --primary: 25 90% 55%;

  --primary-foreground: 40 25% 98%;

  --secondary: 45 75% 65%;

  --secondary-foreground: 210 50% 25%;

  --muted: 30 20% 88%;

  --muted-foreground: 210 30% 45%;

  --accent: 200 35% 92%;

  --accent-foreground: 210 60% 30%;

  --destructive: 5 75% 50%;

  --destructive-foreground: 40 25% 98%;

  --input: 30 20% 80%;
