  --font-sans: 'Inter', system-ui, sans-serif;
  --font-serif: 'Playfair Display', Georgia, serif;
  --font-mono: 'Crimson Text', Georgia, serif;
  --radius: .5rem; /* 8px */
  --shadow-2xs: 0px 2px 0px 0px hsl(200 10% 10% / 0.02);
  --shadow-xs: 0px 2px 0px 0px hsl(200 10% 10% / 0.03);
  --shadow-sm: 0px 2px 0px 0px hsl(200 10% 10% / 0.04), 0px 1px 2px -1px hsl(200 10% 10% / 0.06);
